66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /** Dedicated audit trail for owner-lifecycle side effects. */
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    /** Dedicated trail for the welcome notification enqueued on successful create. */
77	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
78	
79	    /**
80	     * Monotonically increasing sequence stamped onto each {@code OWNER_CREATED} audit
81	     * event, so consumers can order and de-duplicate events across the lifetime of the
82	     * application. Shared across all creates; never reset.
83	     */
84	    private static final AtomicInteger CREATE_SEQUENCE = new AtomicInteger();
85	
86	    /** Serializer for the structured audit event; records serialize by their components. */
87	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
88	
89	    /**
90	     * Immutable structured audit event emitted on owner creation. Its component order
91	     * ({@code seq}, {@code ownerId}, {@code memberId}, {@code membershipLevel},
92	     * {@code event}) is also the field order of the serialized JSON. The
93	     * {@code memberId} slot carries the owner's primary identifier.
94	     */
95	    private record OwnerCreatedEvent(int seq, Integer ownerId, String memberId,
96	                                     Integer membershipLevel, String event) {
97	    }
98	
99	    /** Email domains from disposable/throwaway providers, rejected on create. */
100	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
101	        "mailinator.com", "tempmail.com", "guerrillamail.com");
102	
103	    /** Request header carrying an idempotency token for owner creation. */
104	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
105	
106	    /**
107	     * Remembers the owner created under each seen {@code Idempotency-Key}, so a repeated
108	     * create with an already-seen key returns the original owner (200) instead of creating
109	     * a duplicate. Keyed by the header value, mapped to the created owner's id.
110	     */
111	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
112	
113	    private final ClinicService clinicService;
114	
115	    private final OwnerMapper ownerMapper;
116	
117	    private final PetMapper petMapper;
118	
119	    private final VisitMapper visitMapper;
120	
121	    public OwnerRestControllerV1(ClinicService clinicService,
122	                                 OwnerMapper ownerMapper,
123	                                 PetMapper petMapper,
124	                                 VisitMapper visitMapper) {
125	        this.clinicService = clinicService;
126	        this.ownerMapper = ownerMapper;
127	        this.petMapper = petMapper;
128	        this.visitMapper = visitMapper;
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
134	        Collection<Owner> owners;
135	        if (lastName != null) {
136	            owners = this.clinicService.findOwnerByLastName(lastName);
137	        } else {
138	            owners = this.clinicService.findAllOwners();
139	        }
140	        if (owners.isEmpty()) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
159	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already
160	        // seen, return the owner originally created under it (200) rather than creating a
161	        // duplicate. The key is remembered only after a successful create below.
162	        String idempotencyKey = currentIdempotencyKey();
163	        if (idempotencyKey != null) {
164	            Integer existingId = idempotentCreates.get(idempotencyKey);
165	            if (existingId != null) {
166	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
167	                if (existingOwner != null) {
168	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
169	                }
170	            }
171	        }
172	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
173	        if (normalizedTelephone == null) {
174	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
175	        }
176	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
177	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
178	        }
179	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
180	        // The owner must supply an address in EITHER form: a non-blank structured
181	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
182	        // fields (composing line 1 with an optional line 2) and falls back to the flat
183	        // value; a blank result means neither form was provided. The composed value is
184	        // written back so the persisted flat 'address' stays consistent with it.
185	        String composedAddress = owner.getAddress();
186	        if (composedAddress == null || composedAddress.isBlank()) {
187	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
188	        }
189	        owner.setAddress(composedAddress);
190	        owner.setTelephone(normalizedTelephone);
191	        if (!owner.isPostcodeValidForCity()) {
192	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
193	        }
194	        // The household id is deterministic: it is derived purely from the owner's
195	        // (last name, postcode), so every owner at the same last name and postcode resolves
196	        // to the same value. It is assigned up front, before any duplicate detection, so the
197	        // identity key and the household check below both key off it.
198	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
199	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
200	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
201	        // identityKey (the SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName))
202	        // equals an existing owner's. Because the telephone is part of the key, two owners
203	        // sharing only a last name and postcode differ here whenever their telephone or email
204	        // differs, and so are both allowed (the second is surfaced as a soft match below). This
205	        // single identity key is now the only 409 duplicate check — the former separate
206	        // household-duplicate block keyed on the computed household id no longer applies.
207	        String identityKey = owner.getIdentityKey();
208	        if (this.clinicService.findAllOwners().stream()
209	            .filter(existing -> !existing.isDeleted())
210	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        // The household id is still computed for household-size and membership-level purposes,
214	        // but sharing it no longer rejects the create.
215	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
216	        long ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
217	        if (ownersInCity >= 50) {
218	            return new ResponseEntity<>(HttpStatus.CONFLICT);
219	        }
220	        boolean capacityWarning = ownersInCity >= 40 && ownersInCity <= 49;
221	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
222	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
223	        }
224	        LocalDate effectiveDate =
225	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
226	        LocalDate registrationDate = toBusinessDay(effectiveDate);
227	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
228	        if (ownersRegisteredToday >= 100) {
229	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
230	        }
231	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
232	        HttpHeaders headers = new HttpHeaders();
233	        owner.setRegistrationDate(registrationDate);
234	        owner.setMemberId(memberId(owner));
235	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
236	        owner.setBulkSignupWarning(bulkSignupWarning);
237	        owner.setCapacityWarning(capacityWarning);
238	        // The household size (an input to the membership computation) keys off the computed
239	        // household id: this owner plus everyone already sharing it.
240	        owner.setHouseholdSize(householdMembers.size() + 1);
241	        // Level ceiling: a new owner joining a household they did not explicitly declare
242	        // may not out-rank the household. Cap the derived membership level at one above the
243	        // current maximum among the existing household members; with no existing member no
244	        // cap applies.
245	        if (!sharesHousehold && !householdMembers.isEmpty()) {
246	            int maxHouseholdLevel = householdMembers.stream()
247	                .mapToInt(Owner::getMembershipLevel)
248	                .max()
249	                .orElse(0);
250	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
251	        }
252	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
253	        // duplicate, so only a non-declared create is scored. A non-declared owner whose
254	        // identity key differs from an existing owner's but whose last name (by Soundex) and
255	        // postcode match is flagged here as a possible duplicate rather than rejected.
256	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
257	        owner.setPossibleDuplicate(possibleDuplicate != null);
258	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
259	        this.clinicService.saveOwner(owner);
260	        if (idempotencyKey != null) {
261	            idempotentCreates.put(idempotencyKey, owner.getId());
262	        }
263	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
264	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
265	        emitOwnerCreatedEvent(owner);
266	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
267	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
268	        headers.setLocation(UriComponentsBuilder.newInstance()
269	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
270	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
271	    }
