361	
362	    /**
363	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
364	     * stripped. When a leading {@code '+'} and country code are present they are kept;
365	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
366	     * is dropped from the national digits. The result must be a {@code '+'} followed
367	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
368	     * is returned to signal a bad request.
369	     */
370	    /**
371	     * Build the member id for a newly created owner, formatted
372	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region derived from the
373	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
374	     * derivation the locality uses); {@code FY} is the two-digit fiscal year derived from
375	     * the (business-day-adjusted) registration date; {@code HASH8} is the first eight
376	     * upper-case hex characters of the SHA-256 of the owner's normalized telephone
377	     * concatenated with its last name (the same hash used by the region-and-hash
378	     * identity); and {@code CHK} is a single Luhn check digit computed over the digits of
379	     * {@code <REGION><FY><HASH8>}. On the rare collision with an existing owner's member
380	     * id a {@code '-<n>'} suffix is appended.
381	     */
382	    private String memberId(Owner owner) {
383	        String base = memberIdBase(owner);
384	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
385	            .map(Owner::getMemberId)
386	            .filter(java.util.Objects::nonNull)
387	            .collect(java.util.stream.Collectors.toSet());
388	        if (!existing.contains(base)) {
389	            return base;
390	        }
391	        int n = 2;
392	        while (existing.contains(base + "-" + n)) {
393	            n++;
394	        }
395	        return base + "-" + n;
396	    }
397	
398	    /**
399	     * Build the collision-free base of an owner's member id: {@code <REGION><FY><HASH8>}
400	     * followed by its single Luhn check digit. {@code FY} is the two-digit fiscal year
401	     * taken from {@link Owner#getFiscalYear()} (its {@code 'FY'} prefix stripped), which
402	     * is set by the time the member id is assigned.
403	     */
404	    private String memberIdBase(Owner owner) {
405	        String region = owner.getLocality();
406	        String fiscalYear = owner.getFiscalYear();
407	        String fy = fiscalYear == null ? "" : fiscalYear.substring(2);
408	        String hash8 = memberIdHash(owner.getTelephone(), owner.getLastName());
409	        String core = region + fy + hash8;
410	        return core + luhnCheckDigit(core);
411	    }
412	
413	    /**
414	     * Compute a single Luhn check digit (0-9) over the digits contained in {@code s};
415	     * non-digit characters are ignored and the rightmost digit is doubled first,
416	     * following the standard Luhn algorithm.
417	     */
418	    private int luhnCheckDigit(String s) {
419	        int sum = 0;
420	        boolean doubleDigit = true;
421	        for (int i = s.length() - 1; i >= 0; i--) {
422	            char c = s.charAt(i);
423	            if (c < '0' || c > '9') {
424	                continue;
425	            }
426	            int digit = c - '0';
427	            if (doubleDigit) {
428	                digit *= 2;
429	                if (digit > 9) {
430	                    digit -= 9;
431	                }
432	            }
433	            sum += digit;
434	            doubleDigit = !doubleDigit;
435	        }
436	        return (10 - (sum % 10)) % 10;
437	    }
438	
439	    /**
440	     * Emit the immutable structured {@code OWNER_CREATED} audit event for a freshly
441	     * created owner: a JSON object {@code {seq, ownerId, memberId, membershipLevel,
442	     * event}} logged to the dedicated {@code AUDIT} trail alongside the human-readable
443	     * audit line. Each event is stamped with the next value of the shared monotonic
444	     * sequence, and carries the owner's current primary identifier.
445	     */
446	    private void emitOwnerCreatedEvent(Owner owner) {
447	        OwnerCreatedEvent event = new OwnerCreatedEvent(
448	            CREATE_SEQUENCE.incrementAndGet(),
449	            owner.getId(),
450	            primaryIdentifier(owner),
451	            owner.getMembershipLevel(),
452	            "OWNER_CREATED");
453	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
454	    }
455	
456	    /**
457	     * The owner's primary identifier, as carried by the structured audit event: the
458	     * unified member id.
459	     */
460	    private String primaryIdentifier(Owner owner) {
461	        return owner.getMemberId();
462	    }
463	
464	    /**
465	     * Compute the {@code HASH8} portion of a member id: the first eight upper-case
466	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
467	     * treated as empty when {@code null}), already in their normalized forms.
468	     */
469	    private String memberIdHash(String telephone, String lastName) {
470	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
471	        try {
472	            byte[] digest = MessageDigest.getInstance("SHA-256")
473	                .digest(key.getBytes(StandardCharsets.UTF_8));
474	            StringBuilder sb = new StringBuilder();
475	            for (int i = 0; i < 4; i++) {
476	                sb.append(String.format("%02X", digest[i]));
477	            }
478	            return sb.toString();
479	        }
480	        catch (NoSuchAlgorithmException e) {
481	            throw new IllegalStateException(e);
482	        }
483	    }
484	
485	    /**
486	     * Count the existing owners whose city matches the given one, compared after
487	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
488	     * cap: a city that already holds this many owners is at capacity.
489	     */
490	    private long countOwnersInCity(String city) {
491	        String normalizedCity = normalizeForHousehold(city);
492	        return this.clinicService.findAllOwners().stream()
493	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
494	            .count();
495	    }
496	
497	    /**
498	     * Count the existing owners whose registration date falls on the given day. Used to
499	     * enforce the per-day create limit: once this many owners have been registered today,
500	     * the day is at capacity and further creates are rejected.
501	     */
502	    private long countOwnersRegisteredOn(LocalDate day) {
503	        return this.clinicService.findAllOwners().stream()
504	            .filter(existing -> day.equals(existing.getRegistrationDate()))
505	            .count();
506	    }
507	
508	    /**
509	     * The fixed public holidays that the business-day roll skips. A registration date
510	     * landing on one of these is treated like a weekend and advanced to the next
511	     * non-holiday business day.
512	     */
513	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
514	        LocalDate.parse("2026-01-01"),
515	        LocalDate.parse("2026-01-26"),
516	        LocalDate.parse("2026-04-25"),
517	        LocalDate.parse("2026-12-25"),
518	        LocalDate.parse("2026-12-28"));
519	
520	    /**
521	     * Roll a registration date forward to the next business day: a date falling on a
522	     * Saturday, Sunday or listed public holiday is advanced one day at a time until it
523	     * lands on a non-holiday weekday, while a plain weekday is returned unchanged.
524	     */
525	    private LocalDate toBusinessDay(LocalDate date) {
526	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
527	            date = date.plusDays(1);
528	        }
529	        return date;
530	    }
531	
532	    private static boolean isWeekend(LocalDate date) {
533	        DayOfWeek dayOfWeek = date.getDayOfWeek();
534	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY;
535	    }
536	
537	    /**
538	     * Find the existing owners that already belong to the same household as the given
539	     * computed household id. Because the household id is derived deterministically from
540	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
541	     * that last name and postcode.
542	     */
543	    private List<Owner> findHouseholdMembers(String householdId) {
544	        if (householdId == null) {
545	            return List.of();
546	        }
547	        return this.clinicService.findAllOwners().stream()
548	            .filter(existing -> !existing.isDeleted())
549	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
550	            .toList();
551	    }
552	
553	    /**
554	     * Find an existing owner that this new owner softly duplicates: one whose last name has
555	     * the same Soundex code and whose postcode matches, but whose whole identity key differs
556	     * (an equal identity key is a hard duplicate, already rejected above with 409). Returns
557	     * the lowest-id such owner, or {@code null} when the new owner has no postcode or no soft
558	     * match exists. Owners flagged deleted are ignored.
559	     */
560	    private Owner findPossibleDuplicate(Owner owner) {
561	        String postcode = owner.getPostcode();
562	        if (postcode == null) {
563	            return null;
564	        }
565	        String soundex = Owner.soundex(owner.getLastName());
566	        String identityKey = owner.getIdentityKey();
567	        return this.clinicService.findAllOwners().stream()
568	            .filter(existing -> !existing.isDeleted())
569	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex)
570	                && postcode.equals(existing.getPostcode())
571	                && !identityKey.equals(existing.getIdentityKey()))
572	            .min(java.util.Comparator.comparing(Owner::getId))
573	            .orElse(null);
574	    }
575	
576	    /**
577	     * Count the existing owners that already share both the given first and last
578	     * name, compared case-insensitively. Used to populate an owner's namesake count
579	     * at creation time, reflecting how many owners with the same name existed before
580	     * this one was created.
581	     */
582	    private int countNamesakes(String firstName, String lastName) {
583	        String normalizedFirstName = normalizeName(firstName);
584	        String normalizedLastName = normalizeName(lastName);
585	        return (int) this.clinicService.findAllOwners().stream()
586	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
587	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
588	            .count();
589	    }
590	
591	    private String normalizeName(String value) {
592	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
593	    }
594	
595	    /**
596	     * Build the deterministic identifier shared by all owners of one household: the first
597	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
598	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
599	     * name and postcode resolves to the same value regardless of creation order.
600	     */
601	    private String householdId(String lastName, String postcode) {
602	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
603	        try {
604	            byte[] digest = MessageDigest.getInstance("SHA-256")
605	                .digest(key.getBytes(StandardCharsets.UTF_8));
606	            StringBuilder sb = new StringBuilder();
607	            for (int i = 0; i < 6; i++) {
608	                sb.append(String.format("%02x", digest[i]));
609	            }
610	            return sb.toString();
611	        }
612	        catch (NoSuchAlgorithmException e) {
613	            throw new IllegalStateException(e);
614	        }
615	    }
616	
617	    private String normalizeForHousehold(String value) {
618	        if (value == null) {
619	            return "";
620	        }
621	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
622	    }
623	
624	    /** True when the email's domain is on the disposable-provider blocklist. */
625	    private boolean isDisposableEmailDomain(String email) {
626	        if (email == null) {
627	            return false;
628	        }
629	        int at = email.lastIndexOf('@');
630	        if (at < 0 || at == email.length() - 1) {
631	            return false;
632	        }
633	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
634	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
635	    }
636	
637	    /**
638	     * Read the {@code Idempotency-Key} header from the current request, or {@code null}
639	     * when it is absent or blank (the generated API signature does not expose it, so it is
640	     * pulled from the bound request attributes).
641	     */
642	    private String currentIdempotencyKey() {
643	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
644	            return null;
645	        }
646	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
647	        return (key == null || key.isBlank()) ? null : key;
648	    }
649	
650	    private String normalizeTelephone(String telephone) {
651	        if (telephone == null) {
652	            return null;
653	        }
654	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
655	        String digits;
656	        if (cleaned.startsWith("+")) {
657	            digits = cleaned.substring(1);
658	        } else {
659	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
660	            digits = "61" + national;
661	        }
662	        if (!digits.matches("[0-9]{8,15}")) {
663	            return null;
664	        }
665	        if (!hasValidNationalLength(digits)) {
666	            return null;
667	        }
668	        return "+" + digits;
669	    }
670	
671	    /**
672	     * Validate the national-number length of an E.164 number (the digits, without the
673	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
674	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
675	     * codes without a known rule are accepted as-is.
676	     */
677	    private boolean hasValidNationalLength(String digits) {
678	        if (digits.startsWith("61")) {
679	            return digits.length() - 2 == 9;
680	        }
681	        if (digits.startsWith("1")) {
682	            return digits.length() - 1 == 10;
683	        }
684	        return true;
685	    }
686	
687	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
688	    @Override
689	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
690	        Owner owner = this.clinicService.findOwnerById(ownerId);
691	        if (owner != null) {
692	            Pet pet = owner.getPet(petId);
693	            if (pet != null) {
694	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
695	            }
696	        }
697	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
698	    }
